INSERT INTO public.quiz_questions (id, module_id, question, options, correct_answer, order_index, exercise_type, is_checkpoint, explanation_correct, explanation_wrong) VALUES ('74eb8029-d7a1-5d1b-8898-e0608279ed5d', (SELECT id FROM public.education_modules WHERE slug = 'relationship-vision'), 'Which of these is a sign of psychological safety in a relationship?', '["You never disagree", "You can admit you were wrong without shame", "One partner always makes the final call", "Hard topics are avoided to keep the peace"]'::jsonb, 1, 100, 'multiple_choice', false, 'Psychological safety means you can admit mistakes, ask for things and disagree without being punished for it.', 'Psychological safety means you can admit mistakes, ask for things and disagree without being punished for it.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, module_id, question, options, correct_answer, order_index, exercise_type, is_checkpoint, explanation_correct, explanation_wrong) VALUES ('0d925edf-b5f3-5b10-98d6-85efcffaa50b', (SELECT id FROM public.education_modules WHERE slug = 'relationship-vision'), 'What is the difference between an intention and a resolution?', '["An intention is a direction to move in; a resolution is a pass-or-fail goal", "They mean the same thing", "A resolution is kinder to yourself", "An intention comes with a strict deadline"]'::jsonb, 0, 101, 'multiple_choice', false, 'An intention points you in a direction and allows for setbacks. A resolution is pass-or-fail, which makes it easy to give up.', 'An intention points you in a direction and allows for setbacks. A resolution is pass-or-fail, which makes it easy to give up.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, module_id, question, options, correct_answer, order_index, exercise_type, is_checkpoint, explanation_correct, explanation_wrong) VALUES ('242a9e7f-9a63-5e34-87fb-10e11d806c15', (SELECT id FROM public.education_modules WHERE slug = 'relationship-vision'), 'You want your partner to be more open with you. What does the lesson suggest?', '["Keep asking until they give in", "Model the openness you want to see", "Wait for them to change first", "Point out each time they hold back"]'::jsonb, 1, 102, 'multiple_choice', false, 'People follow what you do more than what you say. Being open yourself makes openness feel safe.', 'People follow what you do more than what you say. Being open yourself makes openness feel safe.') ON CONFLICT (id) DO NOTHING;
