DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.module_sections s JOIN public.education_modules m ON m.id = s.module_id WHERE m.slug = ANY(ARRAY['relationship-orientations','self-image-inner-blueprint','divine-matrix-science-of-intention','embodied-leadership-be-the-change']::text[])) THEN RAISE EXCEPTION 'restructure: a module to delete still has lessons'; END IF; END $$;
